import { useState } from "react";
import { Button, Stack } from "@staqforce-studio/staqui/html";
function Example() {
    const [count, setCount] = useState(0);
    return (element(Stack, { gap: "3" },
        element(Stack, { direction: "row", gap: "3", align: "center" },
            element(Button, { variant: "primary", onClick: () => setCount(count + 1) },
                "Add item (",
                count,
                ")"),
            element(Button, { onClick: () => setCount(0) }, "Reset"),
            element(Button, { variant: "tertiary", onClick: () => setCount(count + 1) }, "Add another")),
        element(Stack, { direction: "row", gap: "3", align: "center" },
            element(Button, { size: "small" }, "Small"),
            element(Button, { size: "medium" }, "Medium"),
            element(Button, { size: "large" }, "Large")),
        element(Stack, { direction: "row", gap: "3", align: "center" },
            element(Button, { variant: "primary", loading: true }, "Saving"),
            element(Button, { disabled: true }, "Unavailable"),
            element(Button, { tone: "critical", onClick: () => setCount(Math.max(0, count - 1)) }, "Remove item"))));
}

